mapper.update:
update oa_sign_task_hard_delete_operation
set processed_count = #{processedCount},
    result_json = #{resultJson},
    lease_expires_time = #{leaseExpiresTime},
    version = version + 1,
    updated_time = sysdate()
where operation_id = #{operationId}
  and status = 'PROCESSING'
  and version = #{version}
  and claim_token = #{claimToken}
  and processed_count = #{expectedProcessedCount}
  and #{processedCount} = processed_count + 1
  and #{processedCount} <= total_count
